// Turns each fetched deal into a Brickfolio price observation. Adapt the field names to your source.
// Expected input per item (e.g. a Google Sheet row you fill in by hand): set, price, currency, url, retailer, condition.
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const set = String(d.set ?? d['Set'] ?? '').trim();
  const price = Number(d.price ?? d['Price']);
  if (!set || !(price > 0)) continue;
  const retailer = String(d.retailer ?? d['Retailer'] ?? 'lego').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  out.push({
    kind: 'set',
    id: set,                                  // 75192, 75192-1 or the box barcode
    source: `retailer:${retailer}`,          // never bricklink, brickowl, brickeconomy or brickset
    type: 'offer',
    condition: String(d.condition ?? 'N').toUpperCase().startsWith('U') ? 'U' : 'N',
    currency: String(d.currency ?? 'USD').toUpperCase(),
    amount: Math.round(price * 100) / 100,
    url: typeof d.url === 'string' && d.url.startsWith('https://') ? d.url : undefined,
    observedAt: new Date().toISOString(),
  });
}
return [{ json: { observations: out.slice(0, 200) } }];
